class Solution {
  public int minimumLevels(int[] possible) {
    int total = 0;
    for (int x : possible) total += x == 1 ? 1 : -1;
    int first = 0;
    for (int i = 0; i < possible.length - 1; i++) {
      first += possible[i] == 1 ? 1 : -1;
      if (first > total - first) return i + 1;
    }
    return -1;
  }
}
